import type { BadgeProps } from "./badge.types";
import type { CSSObject, Theme } from "@emotion/react";
import type { ComponentStyleVariantConfig } from "@types";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "Badge";

// Generate child element class names for the component, should match available style slots
export const BadgeClasses = {
  root: "exp-textura_badge",
  roomy: "exp-textura_badge_roomy",
  dotLg: "exp-textura_badge_dot-lg",
  dotSm: "exp-textura_badge_dot-sm",
};

// Set up style variant settings for the component (if more than "default"), using style slots
const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
  critical: {
    root: {
      backgroundColor: theme.badge.default.critical.color.background,
      color: theme.badge.default.critical.color.content,
    },
    roomy: {
      backgroundColor: theme.badge.roomy.critical.color.background,
      color: theme.badge.roomy.critical.color.content,
    },
    dotLg: {
      backgroundColor: theme.badge.dotLg.critical.color.background,
      color: theme.badge.dotLg.critical.color.content,
    },
    dotSm: {
      backgroundColor: theme.badge.dotSm.critical.color.background,
      color: theme.badge.dotSm.critical.color.content,
    },
  },
  info: {
    root: {
      backgroundColor: theme.badge.default.info.color.background,
      color: theme.badge.default.info.color.content,
    },
    roomy: {
      backgroundColor: theme.badge.roomy.info.color.background,
      color: theme.badge.roomy.info.color.content,
    },
    dotLg: {
      backgroundColor: theme.badge.dotLg.info.color.background,
      color: theme.badge.dotLg.info.color.content,
    },
    dotSm: {
      backgroundColor: theme.badge.dotSm.info.color.background,
      color: theme.badge.dotSm.info.color.content,
    },
  },
  neutral: {
    root: {
      backgroundColor: theme.badge.default.neutral.color.background,
      color: theme.badge.default.neutral.color.content,
    },
    roomy: {
      backgroundColor: theme.badge.roomy.neutral.color.background,
      color: theme.badge.roomy.neutral.color.content,
    },
    dotLg: {
      backgroundColor: theme.badge.dotLg.neutral.color.background,
      color: theme.badge.dotLg.neutral.color.content,
    },
    dotSm: {
      backgroundColor: theme.badge.dotSm.neutral.color.background,
      color: theme.badge.dotSm.neutral.color.content,
    },
  },
  success: {
    root: {
      backgroundColor: theme.badge.default.success.color.background,
      color: theme.badge.default.success.color.content,
    },
    roomy: {
      backgroundColor: theme.badge.roomy.success.color.background,
      color: theme.badge.roomy.success.color.content,
    },
    dotLg: {
      backgroundColor: theme.badge.dotLg.success.color.background,
      color: theme.badge.dotLg.success.color.content,
    },
    dotSm: {
      backgroundColor: theme.badge.dotSm.success.color.background,
      color: theme.badge.dotSm.success.color.content,
    },
  },
  warning: {
    root: {
      backgroundColor: theme.badge.default.warning.color.background,
      color: theme.badge.default.warning.color.content,
    },
    roomy: {
      backgroundColor: theme.badge.roomy.warning.color.background,
      color: theme.badge.roomy.warning.color.content,
    },
    dotLg: {
      backgroundColor: theme.badge.dotLg.warning.color.background,
      color: theme.badge.dotLg.warning.color.content,
    },
    dotSm: {
      backgroundColor: theme.badge.dotSm.warning.color.background,
      color: theme.badge.dotSm.warning.color.content,
    },
  },
});

const generateStyles = (props: BadgeProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<BadgeProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    display: "inline-flex",
    alignItems: "center",
    justifyContent: "center",
    borderRadius: theme.toRem(theme.border.radius.lg),
    padding: `0 ${theme.toRem(2)}`,
    backgroundColor: theme.badge.default.attention.color.background,
    color: theme.badge.default.attention.color.content,
    fontSize: theme.typography.micro.sm.fontSize,
    fontWeight: theme.typography.fontWeight[600],
    lineHeight: theme.toRem(8),
    letterSpacing: theme.typography.letterSpacing.smMinus,
    minHeight: theme.toRem(12),
    maxHeight: theme.toRem(12),
    minWidth: theme.toRem(12),

    [`&.${BadgeClasses.roomy}`]: {
      backgroundColor: theme.badge.roomy.attention.color.background,
      color: theme.badge.roomy.attention.color.content,
      padding: `${theme.toRem(theme.spacing[0])} ${theme.toRem(theme.spacing[4])}`,
      minHeight: theme.toRem(16),
      maxHeight: theme.toRem(16),
      minWidth: theme.toRem(16),
      fontSize: theme.typography.micro.sm.fontSize,
      fontWeight: theme.typography.fontWeight[600],
      ...styleSlots?.roomy,
    },

    [`&.${BadgeClasses.dotLg}`]: {
      backgroundColor: theme.badge.dotLg.attention.color.background,
      color: theme.badge.dotLg.attention.color.content,
      padding: 0,
      minHeight: theme.toRem(10),
      maxHeight: theme.toRem(10),
      width: theme.toRem(10),
      minWidth: theme.toRem(10),
      ...styleSlots?.dotLg,
    },

    [`&.${BadgeClasses.dotSm}`]: {
      backgroundColor: theme.badge.dotSm.attention.color.background,
      color: theme.badge.dotSm.attention.color.content,
      minHeight: theme.toRem(8),
      maxHeight: theme.toRem(8),
      width: theme.toRem(8),
      minWidth: theme.toRem(8),
      padding: 0,
      ...styleSlots?.dotSm,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledBadge = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<BadgeProps>((props) => generateStyles(props));
